sys_script_include.script:
var SettlementRecommender = Class.create();
SettlementRecommender.prototype = {
    initialize: function() {},

    // Calculates a settlement range for a claim, based on similar historical claims.
    // Fills in the result fields but does NOT save.
    evaluate: function(claimGr) {
        var claimType = claimGr.getValue('claim_type');
        var claimAmount = parseFloat(claimGr.getValue('claim_amount_requested')) || 0;

        if (!claimType || claimAmount <= 0) {
            claimGr.setValue('settlement_recommendation', 'Not enough data to recommend a range');
            claimGr.setValue('settlement_reference_claims', '');
            return;
        }

        // 1. Gather all historical claims of the same type
        var candidates = [];
        var hist = new GlideRecord('x_snc_insurance_0_historical_claim');
        hist.addQuery('claim_type', claimType);
        hist.query();

        while (hist.next()) {
            var claimed = parseFloat(hist.getValue('amount_claimed')) || 0;
            var settled = parseFloat(hist.getValue('amount_settled')) || 0;
            if (claimed > 0) {
                candidates.push({
                    ref: hist.getValue('claim_reference'),
                    claimed: claimed,
                    settled: settled,
                    diff: Math.abs(claimed - claimAmount)
                });
            }
        }

        if (candidates.length === 0) {
            claimGr.setValue('settlement_recommendation', 'No similar historical claims found');
            claimGr.setValue('settlement_reference_claims', '');
            return;
        }

        // 2. Pick the 3 closest by claimed amount
        candidates.sort(function(a, b) { return a.diff - b.diff; });
        var closest = candidates.slice(0, Math.min(3, candidates.length));

        // 3. Average settlement ratio among those closest matches
        var totalRatio = 0;
        var refList = [];
        for (var i = 0; i < closest.length; i++) {
            totalRatio += closest[i].settled / closest[i].claimed;
            refList.push(closest[i].ref);
        }
        var avgRatio = totalRatio / closest.length;

        // 4. Suggest a range: a few percent either side of the average ratio applied to this claim
        var midpoint = claimAmount * avgRatio;
        var low = Math.round(midpoint * 0.95 / 1000) * 1000;
        var high = Math.round(midpoint * 1.05 / 1000) * 1000;

        claimGr.setValue('settlement_recommendation',
            'Rs. ' + low.toLocaleString('en-IN') + ' - Rs. ' + high.toLocaleString('en-IN'));
        claimGr.setValue('settlement_reference_claims',
            'Based on ' + closest.length + ' similar claim(s): ' + refList.join(', '));
    },

    // Re-calculates a claim's settlement recommendation by its sys_id and saves it.
    recalculate: function(claimSysId) {
        var claimGr = new GlideRecord('x_snc_insurance_0_claim');
        if (claimGr.get(claimSysId)) {
            this.evaluate(claimGr);
            claimGr.update();
        }
    },

    type: 'SettlementRecommender'
};
